3	/**
4	 * Thrown by {@link org.springframework.samples.petclinic.rest.function.owner.EnsureCityCapacity}
5	 * when the city of the owner being created already contains 50 or more owners. Handled by
6	 * {@link CityAtCapacityExceptionHandler}, which responds 409.
7	 */
8	public class CityAtCapacityException extends Exception {
9	
10	    public CityAtCapacityException(String message) {
11	        super(message);
12	    }
13	}
