1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.beans.factory.annotation.Autowired;
7	import org.springframework.data.domain.Page;
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.repository.OwnerRepository;
10	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
11	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
12	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
13	
14	import java.time.LocalDate;
15	import java.util.Collection;
16	import java.util.List;
17	
18	/**
19	 * Maps Owner & OwnerDto using Mapstruct
20	 */
21	@Mapper(uses = PetMapper.class)
22	public abstract class OwnerMapper {
23	
24	    /**
25	     * More than this many owners already sharing a {@code registrationDate} raises the
26	     * {@code bulkSignupWarning} on responses for that day.
27	     */
28	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
29	
30	    @Autowired
31	    protected OwnerRepository ownerRepository;
32	
33	    @Mapping(target = "displayName",
34	            expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
35	    @Mapping(target = "salutation", expression = "java(salutation(owner))")
36	    @Mapping(target = "initials",
37	            expression = "java(Character.toUpperCase(owner.getFirstName().charAt(0)) + \".\" + Character.toUpperCase(owner.getLastName().charAt(0)) + \".\")")
38	    @Mapping(target = "fiscalYear", expression = "java(fiscalYear(owner))")
39	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
40	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
41	    @Mapping(target = "membershipPoints", expression = "java(membershipPoints(owner))")
42	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
43	    @Mapping(target = "locality", expression = "java(locality(owner))")
44	    @Mapping(target = "timezone", expression = "java(timezone(owner))")
45	    @Mapping(target = "bulkSignupWarning", expression = "java(bulkSignupWarning(owner))")
46	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
47	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
48	    @Mapping(target = "identityKey",
49	            expression = "java(org.springframework.samples.petclinic.rest.function.owner.OwnerIdentity.key(owner))")
50	    @Mapping(target = "telephoneDisplay",
51	            expression = "java(org.springframework.samples.petclinic.rest.function.owner.Telephones.toDisplay(owner.getTelephone()))")
52	    @Mapping(target = "selfLink", expression = "java(selfLink(owner))")
53	    public abstract OwnerDto toOwnerDto(Owner owner);
54	
55	    /**
56	     * The canonical API path to this owner: {@code /api/owners/} followed by the owner's id.
57	     * Returns {@code null} when the owner has no id (e.g. before it has been persisted).
58	     */
59	    protected String selfLink(Owner owner) {
60	        return owner.getId() == null ? null : "/api/owners/" + owner.getId();
61	    }
62	
63	    /**
64	     * The owner's {@code membershipPoints}: the raw loyalty score (see
65	     * {@link org.springframework.samples.petclinic.rest.function.owner.Memberships}), built from a
66	     * present email, no namesakes, a household of 3 or more and tenure over one elapsed fiscal year.
67	     */
68	    protected int membershipPoints(Owner owner) {
69	        long householdSize = org.springframework.samples.petclinic.rest.function.owner.Households
70	                .size(owner, ownerRepository);
71	        return org.springframework.samples.petclinic.rest.function.owner.Memberships
72	                .membershipPoints(owner, householdSize);
73	    }
74	
75	    /**
76	     * The owner's {@code membershipLevel}: the grade {@code membershipPoints} buckets into — 1 for
77	     * 0-1 points, 2 for 2-3, 3 for 4-5 and 4 for 6 or more — after the household level ceiling, which
78	     * caps a member at one above the current maximum level among the household members that already
79	     * existed when it joined (see
80	     * {@link org.springframework.samples.petclinic.rest.function.owner.Memberships#cappedLevel}).
81	     */
82	    protected int membershipLevel(Owner owner) {
83	        return org.springframework.samples.petclinic.rest.function.owner.Memberships
84	                .cappedLevel(owner, ownerRepository);
85	    }
86	
87	    /**
88	     * The owner's preferred contact channel: {@code EMAIL} when an email address is
89	     * present (non-null and non-blank), otherwise {@code PHONE}.
90	     */
91	    protected OwnerDto.ContactPreferenceEnum contactPreference(Owner owner) {
92	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
93	        return hasEmail ? OwnerDto.ContactPreferenceEnum.EMAIL : OwnerDto.ContactPreferenceEnum.PHONE;
94	    }
95	
96	    /** The age (in years) at which an owner stops being a minor and becomes an adult. */
97	    private static final int ADULT_AGE = 18;
98	
99	    /** The age (in years) at which an owner becomes a senior. */
100	    private static final int SENIOR_AGE = 65;
101	
102	    /**
103	     * Derives the owner's {@code ageBand} from {@code birthDate} as of the
104	     * {@code registrationDate}: {@code MINOR} when under {@value #ADULT_AGE},
105	     * {@code ADULT} when {@value #ADULT_AGE} to {@value #SENIOR_AGE}-1, and
